{%- set HYTK = ':opensource' %}
{%- set hy_start_token = '<｜hy_start{}｜>'.format(HYTK) %}
{%- set hy_middle_token = '<｜hy_middle{}｜>'.format(HYTK) %}
{%- set hy_end_token = '<｜hy_end{}｜>'.format(HYTK) %}
{%- set think_begin_token = '<think{}>'.format(HYTK) %}
{%- set think_end_token = '</think{}>'.format(HYTK) %}
